PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS anonymous_devices (id TEXT PRIMARY KEY, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS schedules (id TEXT PRIMARY KEY, device_id TEXT NOT NULL, title TEXT NOT NULL DEFAULT 'My CLSU Schedule', semester TEXT NOT NULL DEFAULT '', academic_year TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(device_id) REFERENCES anonymous_devices(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_schedules_device ON schedules(device_id);
CREATE TABLE IF NOT EXISTS classes (id TEXT PRIMARY KEY, schedule_id TEXT NOT NULL, subject_code TEXT NOT NULL, subject_name TEXT NOT NULL, section TEXT NOT NULL DEFAULT '', day INTEGER NOT NULL CHECK(day BETWEEN 0 AND 5), start_time TEXT NOT NULL, end_time TEXT NOT NULL, room TEXT NOT NULL DEFAULT '', units INTEGER NOT NULL DEFAULT 0 CHECK(units BETWEEN 0 AND 30), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(schedule_id) REFERENCES schedules(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_classes_schedule ON classes(schedule_id);
